            if board[i][j] == 'U' and i % 2 == 0:
                free_cells.append((i, j))
            elif board[i][j] == 'D' and (i + 1) % 2 == 0:
                free_cells.append((i, j))
            elif board[i][j] == 'L' and j % 2 == 0:
                free_cells.append((i, j))
            elif board[i][j] == 'R' and (j + 1) % 2 == 0:
                free_cells.append((i, j))
    return free_cells

def can_move(board, i1, j1, i2, j2):
    if i1 == i2:
        if j1 > j2:
            j1, j2 = j2, j1
        for j in range(j1 + 1, j2):
            if board[i1][j] != '':
                return False
        return True
